import React, { useEffect, useState, useRef, useCallback } from "react";
import axios from "axios";
import Product from "./Product";
import "./ProductList.scss";

const ProductList = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(1); // Página atual
  const [hasMore, setHasMore] = useState(true); // Verifica se há mais produtos para carregar
  const observer = useRef(); // Referência para o Intersection Observer

  // Função para carregar produtos
  const loadProducts = async (page) => {
    setLoading(true);
    try {
      const response = await axios.get(`/products.json?page=${page}&limit=10`); // Ajuste a URL e os parâmetros conforme sua API
      if (Array.isArray(response.data)) {
        setProducts((prevProducts) => [...prevProducts, ...response.data]); // Adiciona novos produtos à lista existente
        setHasMore(response.data.length > 0); // Verifica se há mais produtos para carregar
      } else {
        throw new Error("Dados inválidos: esperado um array de produtos");
      }
    } catch (error) {
      console.error("Erro ao carregar os produtos:", error);
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  // Efeito para carregar produtos quando a página muda
  useEffect(() => {
    loadProducts(page);
  }, [page]);

  // Configuração do Intersection Observer para detectar o final da página
  const lastProductRef = useCallback(
    (node) => {
      if (loading) return; // Não faz nada se já estiver carregando
      if (observer.current) observer.current.disconnect(); // Desconecta o observer anterior

      observer.current = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting && hasMore) {
          setPage((prevPage) => prevPage + 1); // Carrega a próxima página
        }
      });

      if (node) observer.current.observe(node); // Observa o último elemento da lista
    },
    [loading, hasMore]
  );

  if (error) {
    return <div className="error">Erro: {error}</div>;
  }

  return (
    <div className="product-page">
      {/* Opções de Filtro e Ordenação */}
      <div className="product-filters">
        <span>FILTRAR POR ▼</span>
        <span>ORDENAR POR ▼</span>
      </div>

      {/* Grid de Produtos */}
      <div className="product-list">
        {products.map((product, index) => {
          // Adiciona a referência ao último produto da lista
          if (products.length === index + 1) {
            return (
              <div ref={lastProductRef} key={product.productId}>
                <Product product={product} />
              </div>
            );
          } else {
            return <Product key={product.productId} product={product} />;
          }
        })}
      </div>

      {/* Mensagem de carregamento */}
      {loading && <div className="loading">Carregando...</div>}

      {/* Mensagem quando não há mais produtos */}
      {!hasMore && <div className="no-more-products">Não há mais produtos.</div>}
    </div>
  );
};

export default ProductList;
